-- evt:qf1_eye
RegisterEvent(53, "The Eye of the Dragon", function(continueStep)
    if continueStep == 2 then
        XeenQuests.hook("q-f1.eye")
        return
    end
    if continueStep ~= nil then
        XeenQuests.hook("q-f1.eye_wrong")
        return
    end
    if not (not (IsQBitSet(QBit(114021)))) then
        XeenQuests.hook("q-f1.eye")
        return
    end
    evt.SetMessage("\"Look into the eye of the Dragon and despair\"\n\"Answer correctly or perish!\"")
    evt.AskQuestion(53, 1, 0, 2, "\"What is the secret of the Dragon?\"", {"Infinity", "Infinite"})
end, "The Eye of the Dragon")

